            {
                sWhere = " AND StopId<> N'" + moStopMasterStruct.miStopId + "'";
            }
            string sSelectStatement = "SELECT COUNT(*) " +
                " FROM Transport.StopMaster " +
                "  WHERE " +
                " SchoolId = " + moStopMasterStruct.miSchoolId +
                " AND Academic_Year_Id = " + moStopMasterStruct.miAcademicYearId +
                " AND Is_Deleted=0 " +
                " AND StopName= N'" + StringUtility.ReplaceSingleQuoteInString(moStopMasterStruct.msStopName, false) + "'" +
                  sWhere;
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                int iDuplicateStopCount = oSQLServerDbUtility.PerformIntQueryOnSqlServer(sSelectStatement);
                if (iDuplicateStopCount > 0)
