        public StopDetails GetStopDetails(int aiStopId)
        {         
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("StopId", aiStopId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("SchoolId", this.miSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", this.miAcademicYearId, SqlDbType.Int);
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetStopDetails"))
                {
                    StopDetails oStopDetails = new StopDetails();
                    oSqlDataReader.Read();
                    oStopDetails.StopId = Convert.ToInt32(oSqlDataReader["StopId"]);
                    oStopDetails.StopName = Convert.ToString(oSqlDataReader["StopName"]);
